(()=>{
'use strict';
function carbonHydrogens(atoms,bonds,distance){const result=[];for(const a of atoms.filter(a=>a.label==='C')){const links=bonds.filter(b=>b[0]===a.id||b[1]===a.id),count=4-links.reduce((sum,b)=>sum+b[2],0),angles=links.map(b=>{const q=atoms.find(v=>v.id===(b[0]===a.id?b[1]:b[0]));return Math.atan2(q.y-a.y,q.x-a.x);});for(let i=0;i<count;i++){let best=0,score=-1;for(let k=0;k<24;k++){const angle=k*Math.PI/12,min=Math.min(...angles.map(v=>Math.acos(Math.cos(angle-v))));if(min>score){score=min;best=angle;}}angles.push(best);result.push({x:a.x+distance*Math.cos(best),y:a.y+distance*Math.sin(best),parent:a});}}return result;}

const dirs=[[1,0],[-1,0],[0,1],[0,-1]],cell=(x,y)=>x+','+y;
function adjacency(nodes,edges){const adj=nodes.map(()=>[]);for(const [a,b] of edges){adj[a].push(b);adj[b].push(a);}return adj;}
function pathFrom(adj,start,end){const prev=Array(adj.length).fill(-1),queue=[start];prev[start]=start;for(let k=0;k<queue.length;k++){const a=queue[k];if(a===end)break;for(const b of adj[a])if(prev[b]===-1){prev[b]=a;queue.push(b);}}if(prev[end]===-1)return [];const path=[end];while(path.at(-1)!==start)path.push(prev[path.at(-1)]);return path.reverse();}
function longest(adj){let best=[];const ends=adj.map((a,i)=>a.length===1?i:-1).filter(i=>i>=0);for(let i=0;i<ends.length;i++)for(let j=i+1;j<ends.length;j++){const p=pathFrom(adj,ends[i],ends[j]);if(p.length>best.length)best=p;}return best;}

const parents=['','methane','ethane','propane','butane','pentane','hexane','heptane','octane'],alkyl=['','methyl','ethyl','propyl'];
function branches(adj,path){const used=new Set(path),out=[];path.forEach((a,index)=>{for(const b of adj[a])if(!used.has(b)){const ids=[],stack=[[b,a]];while(stack.length){const [v,prev]=stack.pop();ids.push(v);for(const w of adj[v])if(w!==prev)stack.push([w,v]);}out.push({ids,locant:index+1,name:alkyl[ids.length]||'',linear:ids.every(v=>adj[v].length<=2)});}});return out;}
function candidates(adj){const ends=adj.map((a,i)=>a.length===1?i:-1).filter(i=>i>=0);let paths=[];for(let i=0;i<ends.length;i++)for(let j=i+1;j<ends.length;j++)paths.push(pathFrom(adj,ends[i],ends[j]));const n=Math.max(...paths.map(p=>p.length));paths=paths.filter(p=>p.length===n);const count=Math.max(...paths.map(p=>branches(adj,p).length));return paths.filter(p=>branches(adj,p).length===count);}
function compare(a,b){for(let i=0;i<a.length;i++)if(a[i]!==b[i])return a[i]-b[i];return 0;}
function directionScore(bs,n){const forward=bs.map(b=>b.locant).sort((a,b)=>a-b),reverse=bs.map(b=>n+1-b.locant).sort((a,b)=>a-b);const primary=compare(forward,reverse);if(primary)return primary;for(const name of [...new Set(bs.map(b=>b.name))].sort()){const same=bs.filter(b=>b.name===name);const c=compare(same.map(b=>b.locant).sort((a,b)=>a-b),same.map(b=>n+1-b.locant).sort((a,b)=>a-b));if(c)return c;}return 0;}
function moleculeName(parent,bs,n,reverse=false){const groups={};for(const b of bs){const key=b.name||'?';(groups[key]??=[]).push(b.locant?(reverse?n+1-b.locant:b.locant):'?');}return Object.keys(groups).sort().map(name=>{const ns=groups[name].sort((a,b)=>a-b),prefix=['','','di','tri','tetra','penta','hexa','hepta','octa'][ns.length]||'';return ns.join(',')+'-'+prefix+name;}).join('-')+(parent||'[parent name]');}
function generate(random=Math.random){for(let attempt=0;attempt<300;attempt++){const target=9+Math.floor(random()*6),nodes=[{x:0,y:0}],edges=[],occupied=new Map([[cell(0,0),0]]);while(nodes.length<target){const adj=adjacency(nodes,edges),options=[];nodes.forEach((p,parent)=>{if(adj[parent].length>=4)return;for(const [dx,dy] of dirs){const x=p.x+dx,y=p.y+dy;if(occupied.has(cell(x,y))||dirs.filter(([sx,sy])=>occupied.has(cell(x+sx,y+sy))).length!==1)continue;const trial=adj.map(a=>a.slice());trial.push([parent]);trial[parent].push(nodes.length);if(longest(trial).length<=8)options.push({x,y,parent});}});if(!options.length)break;const q=options[Math.floor(random()*options.length)];edges.push([q.parent,nodes.length]);occupied.set(cell(q.x,q.y),nodes.length);nodes.push({x:q.x,y:q.y});}const adj=adjacency(nodes,edges),paths=candidates(adj);if(paths[0].length<4)continue;const sets=paths.map(p=>branches(adj,p));if(sets.some(bs=>bs.length<2||bs.some(b=>!b.linear||!b.name)))continue;const names=sets.map((bs,i)=>moleculeName(parents[paths[i].length],bs,paths[i].length,directionScore(bs,paths[i].length)>0));if(new Set(names).size!==1)continue;return {nodes,edges,adj,solution:paths[0],paths};}
const nodes=[{x:0,y:0},{x:1,y:0},{x:2,y:0},{x:3,y:0},{x:1,y:1},{x:2,y:-1}],edges=[[0,1],[1,2],[2,3],[1,4],[2,5]],adj=adjacency(nodes,edges),paths=candidates(adj);return {nodes,edges,adj,solution:paths[0],paths};}
class Chain{
 constructor(random=Math.random){this.random=random;this.newStructure();}
 newStructure(){this.tree=generate(this.random);this.clear();}
 clear(){this.selected=[];this.parent='';this.step=1;this.records=[];this.active=-1;this.reverse=false;this.direction=null;this.solved=false;}
 choose(id){if(this.step!==1){const bs=branches(this.tree.adj,this.selected),b=bs.find(b=>b.ids.includes(id));if(!b)return {ok:false,text:'Select a carbon in a side branch.'};let index=this.records.findIndex(r=>r.ids.includes(id));if(index<0){index=this.records.length;this.records.push({ids:b.ids,name:'',locant:0});}this.active=index;return {ok:true,text:''};}const previous=this.selected.indexOf(id);if(previous>=0){this.selected=this.selected.slice(0,previous===this.selected.length-1?previous:previous+1);return {ok:true,text:''};}if(!this.selected.length&&this.tree.adj[id].length!==1)return {ok:false,text:'Start at an end carbon.'};if(this.selected.length&&!this.tree.adj[this.selected.at(-1)].includes(id))return {ok:false,text:'Choose a carbon bonded to the last numbered carbon.'};this.selected.push(id);return {ok:true,text:''};}
 undo(){this.selected.pop();}
 check(){const fail=text=>({ok:false,text});if(this.step===1){if(this.selected.length!==this.tree.solution.length)return fail('A longer continuous chain is possible. Try another route.');const bs=branches(this.tree.adj,this.selected);if(bs.length!==branches(this.tree.adj,this.tree.solution).length)return fail('For equally long chains, choose the one with more side branches.');if(this.parent!==parents[this.selected.length])return fail('Check the parent name against the number of carbons in your chain.');this.step=2;return {ok:true,text:'Parent chain correct. Select each side branch, then give its name and position.'};}if(this.step===2){const bs=branches(this.tree.adj,this.selected);if(this.records.length!==bs.length)return fail('There are still side branches to identify.');for(const b of bs){const r=this.records.find(r=>r.ids.includes(b.ids[0]));if(!r||r.name!==b.name||r.locant!==b.locant)return fail('Check each branch’s carbon count and the parent-chain number where it joins.');}this.step=3;this.active=-1;return {ok:true,text:'Branches correct. Choose the end that gives the preferred numbering.'};}if(this.direction===null)return fail('Choose end A or end B.');const score=directionScore(branches(this.tree.adj,this.selected),this.selected.length);if((score<0&&this.reverse)||(score>0&&!this.reverse))return fail('Compare the sorted branch positions: the first differing number should be smaller. If tied, give the alphabetically first branch the lower position.');this.solved=true;return {ok:true,text:'Correct — '+this.name()+'.'};}
 name(){return moleculeName(this.parent,this.records,this.selected.length,this.reverse);}
}
if(typeof module!=='undefined'&&module.exports)module.exports={carbonHydrogens,generate,adjacency,pathFrom,longest,branches,candidates,directionScore,moleculeName,parents,Chain};if(typeof document==='undefined')return;
const $=id=>document.getElementById('lc-'+id);if(!$('game'))return;const game=new Chain();let showHydrogen=false;
function feedback(result){$('feedback').hidden=!result||!result.text;$('feedback').textContent=result?result.text:'';$('feedback').classList.toggle('success',!!result&&result.ok&&game.solved);}
$('hydrogen').addEventListener('click',()=>{showHydrogen=!showHydrogen;render();});
function render(){ $('hydrogen').textContent=showHydrogen?'Hide hydrogen':'Show hydrogen';$('hydrogen').setAttribute('aria-pressed',String(showHydrogen));$('hydrogen-note').textContent=showHydrogen?'Hydrogens bonded to carbon are shown.':'Hydrogens bonded to carbon are not shown.';const {nodes,edges}=game.tree,minX=Math.min(...nodes.map(p=>p.x)),maxX=Math.max(...nodes.map(p=>p.x)),minY=Math.min(...nodes.map(p=>p.y)),maxY=Math.max(...nodes.map(p=>p.y)),spacing=Math.min(66,740/Math.max(1,maxX-minX),460/Math.max(1,maxY-minY)),positions=nodes.map(p=>({x:420+(p.x-(maxX+minX)/2)*spacing,y:290+(p.y-(maxY+minY)/2)*spacing}));const pathEdges=new Set(game.selected.slice(1).map((id,i)=>[id,game.selected[i]].sort((a,b)=>a-b).join(',')));let svg='<title>Branched carbon skeleton: select an end and count a continuous chain</title><desc>Carbon atoms and carbon–carbon bonds are shown; carbon-bound hydrogens can be toggled. Select connected carbon atoms in order. The selected atoms display their chain numbers.</desc>';
for(const [a,b] of edges){const p=positions[a],q=positions[b],dx=q.x-p.x,dy=q.y-p.y,len=Math.hypot(dx,dy),selected=pathEdges.has([a,b].sort((a,b)=>a-b).join(','));svg+=`<line x1="${p.x+19*dx/len}" y1="${p.y+19*dy/len}" x2="${q.x-19*dx/len}" y2="${q.y-19*dy/len}" class="lc-bond ${selected?'selected':''}"/>`;}
if(showHydrogen){const atoms=positions.map((p,i)=>({...p,id:i,label:'C'}));for(const h of carbonHydrogens(atoms,edges.map(([a,b])=>[a,b,1]),31)){svg+=`<line x1="${h.parent.x}" y1="${h.parent.y}" x2="${h.x}" y2="${h.y}" class="nh-bond"/><text x="${h.x}" y="${h.y}" class="nh-label">H</text>`;}}
positions.forEach((p,i)=>{const raw=game.selected.indexOf(i)+1,number=raw?(game.reverse?game.selected.length+1-raw:raw):0,branch=game.records.findIndex(r=>r.ids.includes(i));svg+=`<g data-carbon="${i}" role="button" tabindex="0" aria-pressed="${number>0}" aria-label="Carbon at row ${nodes[i].y-minY+1}, column ${nodes[i].x-minX+1}${number?', selected number '+number:''}" class="lc-carbon ${number?'selected':''} ${game.solved&&number?'solved':''} ${branch>=0?'branch':''}"><circle cx="${p.x}" cy="${p.y}" r="26" class="lc-hit"/><circle cx="${p.x}" cy="${p.y}" r="23" class="lc-number-bg"/><text x="${p.x}" y="${p.y}" class="lc-label">${number||(branch>=0?'B'+(branch+1):'C')}</text></g>`;});$('diagram').innerHTML=svg;$('count').textContent=game.selected.length+' carbon'+(game.selected.length===1?'':'s')+' selected';$('undo').hidden=game.step!==1;$('clear').hidden=game.step!==1;$('undo').disabled=!game.selected.length;$('check').disabled=game.step===1&&game.selected.length<2;renderForm();}
function choose(e){const target=e.target.closest('[data-carbon]');if(!target)return;if(game.step===3)return;const id=Number(target.dataset.carbon),result=game.choose(id);feedback(result);render();if(e.type==='keydown')$('diagram').querySelector('[data-carbon="'+id+'"]').focus();}
$('diagram').addEventListener('click',choose);$('diagram').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();choose(e);}});$('check').addEventListener('click',()=>{feedback(game.check());render();});$('undo').addEventListener('click',()=>{game.undo();feedback(null);render();});$('clear').addEventListener('click',()=>{game.clear();feedback(null);render();});$('next').addEventListener('click',()=>{game.newStructure();feedback(null);render();});
function renderForm(){
 $('question').textContent=['','1 · Name the longest carbon chain','2 · Identify side branches and positions','3 · Choose where counting starts'][game.step];
 $('parent-setting').hidden=game.step!==1;$('parent').value=game.parent;$('branch-panel').hidden=game.step!==2;$('direction-panel').hidden=game.step!==3;
 $('branches').innerHTML=game.records.map((r,i)=>`<button type="button" data-branch="${i}" aria-pressed="${game.active===i}">B${i+1} · ${r.name||'Choose name'} · ${r.locant||'?'}</button>`).join('');
 $('branch-form').hidden=game.active<0;const active=game.records[game.active];$('branch-name').value=active?.name||'';$('branch-position').value=active?.locant||'';
 $('draft').textContent=game.name();$('back').hidden=game.step===1;
 $('hint').textContent=game.step===1?'Select connected carbons from an end. Click an earlier number to go back.':game.step===2?'Select an unnumbered carbon to identify its whole branch. Positions use the current numbering.':'End A is the original starting end; end B is the opposite end.';
 ['a','b'].forEach((v,i)=>{$('end-'+v).setAttribute('aria-pressed',String(game.direction===i));});
 if(game.step===3){const labels=$('diagram').querySelectorAll('.lc-carbon.selected');labels.forEach(el=>{const id=Number(el.dataset.carbon);if(id===game.selected[0]||id===game.selected.at(-1)){const t=el.querySelector('text');t.textContent+=(id===game.selected[0]?' · A':' · B');t.style.fontSize='20px';}});}
 document.dispatchEvent(new Event('chemi-controls-sync'));
}
$('parent').addEventListener('change',e=>{game.parent=e.target.value;feedback(null);render();});
$('branches').addEventListener('click',e=>{const b=e.target.closest('[data-branch]');if(b){game.active=Number(b.dataset.branch);render();}});
for(const key of ['name','position'])$('branch-'+key).addEventListener('change',e=>{if(game.active<0)return;game.records[game.active][key==='name'?'name':'locant']=key==='name'?e.target.value:Number(e.target.value);feedback(null);render();});
['a','b'].forEach((v,i)=>$('end-'+v).addEventListener('click',()=>{game.direction=i;game.reverse=!!i;game.solved=false;feedback(null);render();}));
$('back').addEventListener('click',()=>{game.step--;game.solved=false;game.reverse=false;game.direction=null;if(game.step===1){game.records=[];game.active=-1;}feedback(null);render();});
render();
})();
